CREATE FUNCTION public.sync_sale_contract_ledger() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ DECLARE calc_amt NUMERIC; BEGIN IF TG_OP = 'INSERT' AND NEW.status = 1 AND NEW.total_amount > 0 THEN calc_amt := CASE WHEN NEW.after_discount IS NOT NULL AND NEW.after_discount::NUMERIC > 0 AND NEW.after_discount::NUMERIC <= NEW.total_amount THEN NEW.after_discount::NUMERIC ELSE NEW.total_amount END; INSERT INTO ledger_flow (date, type, flow_category, source, amount, contact_name, order_id, order_sn, fund_name, remark, created_by) VALUES (COALESCE(NEW.order_date, NEW.created_at::date, NOW()::date), 'income', 'receivable', '销售合同', calc_amt, NEW.customer_name, NEW.id, NEW.order_sn, '', NEW.remark, 'trigger'); RETURN NEW; ELSIF TG_OP = 'UPDATE' THEN IF OLD.status != 1 AND NEW.status = 1 AND NEW.total_amount > 0 THEN calc_amt := CASE WHEN NEW.after_discount IS NOT NULL AND NEW.after_discount::NUMERIC > 0 AND NEW.after_discount::NUMERIC <= NEW.total_amount THEN NEW.after_discount::NUMERIC ELSE NEW.total_amount END; INSERT INTO ledger_flow (date, type, flow_category, source, amount, contact_name, order_id, order_sn, fund_name, remark, created_by) VALUES (COALESCE(NEW.order_date, NEW.created_at::date, NOW()::date), 'income', 'receivable', '销售合同', calc_amt, NEW.customer_name, NEW.id, NEW.order_sn, '', NEW.remark, 'trigger'); ELSIF OLD.status = 1 AND NEW.status != 1 THEN DELETE FROM ledger_flow WHERE order_id = NEW.id AND source = '销售合同'; ELSIF OLD.status = 1 AND NEW.status = 1 AND (OLD.total_amount != NEW.total_amount OR COALESCE(OLD.after_discount,0) != COALESCE(NEW.after_discount,0)) THEN calc_amt := CASE WHEN NEW.after_discount IS NOT NULL AND NEW.after_discount::NUMERIC > 0 AND NEW.after_discount::NUMERIC <= NEW.total_amount THEN NEW.after_discount::NUMERIC ELSE NEW.total_amount END; UPDATE ledger_flow SET amount = calc_amt WHERE order_id = NEW.id AND source = '销售合同'; END IF; RETURN NEW; ELSIF TG_OP = 'DELETE' THEN DELETE FROM ledger_flow WHERE order_id = OLD.id AND source = '销售合同'; RETURN OLD; END IF; RETURN NULL; END; $$;


ALTER FUNCTION public.sync_sale_contract_ledger() OWNER TO neondb_owner;

--
-- Name: sync_sale_return_ledger(); Type: FUNCTION; Schema: public; Owner: neondb_owner
--

CREATE FUNCTION public.sync_sale_return_ledger() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_cat TEXT;
  v_amt NUMERIC;
BEGIN
  IF TG_OP = 'INSERT' AND COALESCE(NEW.status,0) = 1 THEN
    v_amt := COALESCE(NEW.return_amount, NEW.total_amount, 0);
    IF v_amt > 0 THEN
      v_cat := CASE WHEN NEW.fund_id IS NOT NULL AND NEW.fund_id > 0 THEN 'cash' ELSE 'receivable' END;
      VALUES (COALESCE(NEW.return_date, NEW.created_at::date, NOW()::date),
              'expense', v_cat, '销售退货', v_amt,
              COALESCE(NEW.customer_name,''), NEW.id, NEW.order_sn, NEW.fund_name, NEW.remark, 'trigger');
    END IF;
    RETURN NEW;
  ELSIF TG_OP = 'DELETE' THEN
    DELETE FROM ledger_flow WHERE order_id = OLD.id AND source = '销售退货';
    RETURN OLD;
  ELSIF TG_OP = 'UPDATE' THEN
    IF OLD.status = 1 AND NEW.status != 1 THEN
      DELETE FROM ledger_flow WHERE order_id = NEW.id AND source = '销售退货';
    ELSIF OLD.status != 1 AND NEW.status = 1 THEN
      v_amt := COALESCE(NEW.return_amount, NEW.total_amount, 0);
      IF v_amt > 0 THEN
        v_cat := CASE WHEN NEW.fund_id IS NOT NULL AND NEW.fund_id > 0 THEN 'cash' ELSE 'receivable' END;
        VALUES (COALESCE(NEW.return_date, NEW.created_at::date, NOW()::date),
                'expense', v_cat, '销售退货', v_amt,
                COALESCE(NEW.customer_name,''), NEW.id, NEW.order_sn, NEW.fund_name, NEW.remark, 'trigger');
      END IF;
    END IF;
    RETURN NEW;
  END IF;
  RETURN NULL;
END;
$$;


